<script setup lang="ts">
import { Message } from '@arco-design/web-vue'
import { IconArrowRight, IconCheckCircle, IconEdit, IconRobot, IconClockCircle, IconSafe, IconEmail } from '@arco-design/web-vue/es/icon'

const { state, refresh } = useDemoState()
const form = reactive({ origin:'深圳', destination:'洛杉矶', cargoName:'蓝牙音箱（带电）', weightKg:820, volumeCbm:5.4, preference:'平衡价格与时效', details:{ cargoTraits:'内置锂电池，单件 2.4 KG', sla:'希望 10 天内签收', tradeTerm:'DDP', shipmentDate:'2026-07-24', monthlyVolume:'5–8 CBM', notes:'需要稳定舱位与全程轨迹' } })
const identity = reactive({ email:'test@example.com', companyName:'远舟跨境演示客户', contactName:'陈经理', customerType:'ecommerce_seller' })
const showDetails = ref(false)
const quoteLoading = ref(false)
const identityLoading = ref(false)
const rematchLoading = ref(false)
const sessionId = ref('')
const inquiryId = ref('')
const recommendations = ref<any[]>([])
const selectedProductId = ref('')
const customerId = ref('')
const opportunityId = ref('')
const taskId = ref('')
const phase = ref<'need'|'identity'|'agent'>('need')

const relatedTasks = computed(() => (state.value?.tasks || []).filter(task => task.targetId === customerId.value || task.id === taskId.value).slice(0,4))
const activeTask = computed(() => relatedTasks.value.find(task => ['queued','running','waiting'].includes(task.status)))
const latestTask = computed(() => activeTask.value || relatedTasks.value[0])
const productById = (id:string) => state.value?.products.find(product => product.id === id)

onMounted(() => { void refresh({ quiet:true }) })

async function quote() {
  quoteLoading.value = true
  try {
    const result = await $fetch<any>('/api/website/quote', { method:'POST', body:{ ...form, sessionId:sessionId.value || undefined, inquiryId:inquiryId.value || undefined } })
    sessionId.value = result.sessionId; inquiryId.value = result.inquiryId; recommendations.value = result.recommendations; selectedProductId.value = result.recommendations[0]?.productId || ''; phase.value = 'identity'
    Message.success('已匹配已发布产品，请留资保存本次询价')
    requestAnimationFrame(() => document.getElementById('quote-results')?.scrollIntoView({ behavior:'smooth', block:'start' }))
  } catch (error:any) { Message.error(error?.data?.statusMessage || '查询失败，请检查输入后重试') }
  finally { quoteLoading.value = false }
}
async function identify() {
  if (!selectedProductId.value) return Message.warning('请选择一个产品方案')
  identityLoading.value = true
  try {
    const result = await $fetch<any>('/api/website/identity', { method:'POST', body:{ inquiryId:inquiryId.value, ...identity, selectedProductId:selectedProductId.value } })
    customerId.value = result.customerId; opportunityId.value = result.opportunityId; taskId.value = result.task?.task?.id || ''; phase.value = 'agent'
    Message.info('客户档案已建立，Agent 已开始分析；请勿重复提交')
    await refresh({ quiet:true })
  } catch (error:any) { Message.error(error?.data?.statusMessage || '身份留资失败，请稍后重试') }
  finally { identityLoading.value = false }
}
async function rematch() {
  if (!inquiryId.value) return quote()
  rematchLoading.value = true
  try {
    const result = await $fetch<any>('/api/website/rematch', { method:'POST', body:{ inquiryId:inquiryId.value, ...form } })
    recommendations.value = result.recommendations; selectedProductId.value = result.recommendations[0]?.productId || selectedProductId.value; if (result.task?.task?.id) taskId.value = result.task.task.id
    Message.info(customerId.value ? '询价已更新，Agent 已开始重新匹配' : '询价已更新，推荐结果已刷新')
    await refresh({ quiet:true })
  } catch (error:any) { Message.error(error?.data?.statusMessage || '重新匹配失败') }
  finally { rematchLoading.value = false }
}
function resetFlow() { phase.value='need';sessionId.value='';inquiryId.value='';recommendations.value=[];selectedProductId.value='';customerId.value='';opportunityId.value='';taskId.value='';window.scrollTo({top:0,behavior:'smooth'}) }
function scrollToQuote() { document.getElementById('quote')?.scrollIntoView({ behavior:'smooth' }) }
</script>

<template>
  <div class="marketing-site">
    <header class="site-header"><NuxtLink to="/" class="site-brand"><span class="site-logo">百</span><strong>百运物流</strong></NuxtLink><nav><a href="#services">物流产品</a><a href="#quote">在线询价</a><a href="#agent">AI 物流助手</a></nav><NuxtLink class="admin-link" to="/admin">进入获客演示台 <IconArrowRight /></NuxtLink></header>
    <main>
      <section class="hero"><div class="hero__glow" /><div class="hero__copy"><span class="hero__eyebrow">GLOBAL LOGISTICS · AI POWERED</span><h1>让每一次跨境运输需求<br><em>快速找到合适的产品</em></h1><p>输入路线与货物信息，系统会从百运已发布物流产品中推荐最多 3 个方案。完成留资后，智能获客 Agent 将继续分析并协助后续跟进。</p><div class="hero__trust"><span><IconSafe /> 信息分层保护</span><span><IconClockCircle /> 即时产品匹配</span><span><IconRobot /> Agent 持续跟进</span></div></div><aside class="agent-preview" id="agent"><div class="agent-preview__head"><span class="agent-avatar">✦</span><div><strong>AI 物流助手</strong><small>已连接产品库</small></div><span class="online-dot" /></div><div class="agent-message"><span>✦ AI 助手</span><p>您好，我可以先根据路线、货物和时效偏好，为您匹配百运当前已发布的物流产品。</p></div><div class="agent-chips"><button @click="scrollToQuote">中国 → 美国</button><button @click="scrollToQuote">带电产品</button><button @click="scrollToQuote">对比价格与时效</button></div><div class="agent-input"><span>请输入您的物流需求…</span><button disabled>发送</button></div><small class="agent-note">对话能力接口已预留，本次演示以结构化询价为主</small></aside></section>

      <section id="quote" class="quote-section">
        <div class="section-title"><span>ONLINE QUOTE</span><h2>获取适配的物流产品方案</h2><p>第 1 步填写运输需求，第 2 步留资建立客户档案；提交期间会持续显示真实处理状态。</p></div>
        <div class="quote-layout"><div class="quote-card"><div class="quote-card__head"><div><span class="step-badge">01</span><h2>运输需求</h2></div><span v-if="inquiryId" class="saved-hint"><IconCheckCircle /> 询价已保存</span></div><div class="quote-form"><label><span>始发地 *</span><a-input v-model="form.origin" :disabled="quoteLoading || rematchLoading" /></label><label><span>目的地 *</span><a-input v-model="form.destination" :disabled="quoteLoading || rematchLoading" /></label><label><span>货物名称 *</span><a-input v-model="form.cargoName" :disabled="quoteLoading || rematchLoading" /></label><label><span>预计重量 *</span><a-input-number v-model="form.weightKg" :min="0.1" :disabled="quoteLoading || rematchLoading"><template #suffix>KG</template></a-input-number></label><label><span>预计体积 *</span><a-input-number v-model="form.volumeCbm" :min="0.01" :step="0.1" :disabled="quoteLoading || rematchLoading"><template #suffix>CBM</template></a-input-number></label><div class="field-control"><span>运输偏好 *</span><a-select v-model="form.preference" :disabled="quoteLoading || rematchLoading"><a-option value="平衡价格与时效">平衡价格与时效</a-option><a-option value="优先时效">优先时效</a-option><a-option value="优先价格">优先价格</a-option></a-select></div></div><button class="details-toggle" @click="showDetails=!showDetails"><IconEdit /> {{ showDetails ? '收起补充信息' : '补充货物特性、贸易条款与出货计划' }}</button><Transition name="details"><div v-if="showDetails" class="quote-details"><label><span>货物特性</span><a-input v-model="form.details.cargoTraits" /></label><label><span>期望时效</span><a-input v-model="form.details.sla" /></label><div class="field-control"><span>贸易条款</span><a-select v-model="form.details.tradeTerm"><a-option value="DDP">DDP</a-option><a-option value="DDU">DDU</a-option><a-option value="FOB">FOB</a-option></a-select></div><label><span>计划出货日</span><a-input v-model="form.details.shipmentDate" /></label><label><span>月均货量</span><a-input v-model="form.details.monthlyVolume" /></label><label><span>备注</span><a-input v-model="form.details.notes" /></label></div></Transition><div class="quote-submit"><a-button v-if="inquiryId" size="large" :loading="rematchLoading" :disabled="quoteLoading || Boolean(activeTask)" @click="rematch"><template #icon><IconRobot /></template>修改后重新匹配</a-button><a-button type="primary" size="large" :loading="quoteLoading" :disabled="rematchLoading || Boolean(activeTask)" @click="quote">{{ inquiryId ? '重新查看产品方案' : '查看匹配方案' }}<template #icon><IconArrowRight /></template></a-button></div><div v-if="quoteLoading || rematchLoading" class="inline-progress"><div class="agent-signal"><span/><span/><span/></div><strong>{{ rematchLoading ? '正在重新匹配' : '正在查询已发布产品' }}</strong><p>{{ rematchLoading && customerId ? '修改后的询价将同步到客户档案，并启动 Agent 重新判断。' : '正在根据线路、货物与偏好筛选产品，请勿重复点击。' }}</p></div></div>
          <aside class="quote-aside"><h3>本次演示会记录什么？</h3><ol><li><span>1</span><div><strong>匿名询价</strong><p>只形成访问会话和询价，不建立正式客户。</p></div></li><li><span>2</span><div><strong>完成留资</strong><p>通过邮箱查重并建立或合并客户档案。</p></div></li><li><span>3</span><div><strong>Agent 分析</strong><p>生成客户画像与 Top 3 产品匹配。</p></div></li><li><span>4</span><div><strong>人工建联</strong><p>后台审核建议、邮件和后续机会进度。</p></div></li></ol></aside></div>
      </section>

      <section v-if="recommendations.length" id="quote-results" class="results-section"><div class="section-title"><span>MATCHED PRODUCTS</span><h2>为您匹配的已发布产品</h2><p>以下为演示参考，最终价格、舱位与货物适用性需由人工确认。</p></div><div class="recommend-grid"><article v-for="(rec,index) in recommendations" :key="rec.productId" :class="['recommend-card',{ selected:selectedProductId===rec.productId }]" @click="selectedProductId=rec.productId"><div class="recommend-card__rank">推荐 {{ index+1 }}</div><span class="select-indicator"><IconCheckCircle /></span><div class="recommend-score"><strong>{{ rec.score }}</strong><span>参考匹配分</span></div><h3>{{ rec.name }}</h3><p class="recommend-code">{{ rec.code }} · {{ rec.transitTime }}</p><ul><li v-for="item in rec.evidence" :key="item">{{ item }}</li></ul><div class="recommend-capabilities"><span v-for="item in rec.capabilities.slice(0,3)" :key="item">{{ item }}</span></div><div class="recommend-price"><small>{{ rec.quoteReady ? '模拟参考报价' : '报价状态' }}</small><strong>{{ rec.quoteReady ? rec.referencePrice : '需人工询价' }}</strong></div></article></div>

        <div v-if="phase === 'identity'" class="identity-card"><div class="identity-card__intro"><span class="step-badge">02</span><div><h2>保存方案并由 Agent 继续跟进</h2><p>工作邮箱必填；公司与联系人可稍后补充。提交后会立即显示 Agent 运行状态。</p></div></div><div class="identity-form"><label><span>工作邮箱 *</span><a-input v-model="identity.email" :disabled="identityLoading" /></label><label><span>公司名称</span><a-input v-model="identity.companyName" :disabled="identityLoading" /></label><label><span>联系人</span><a-input v-model="identity.contactName" :disabled="identityLoading" /></label><div class="field-control"><span>客户类型</span><a-select v-model="identity.customerType" :disabled="identityLoading"><a-option value="ecommerce_seller">跨境电商卖家</a-option><a-option value="exporter">出口企业</a-option><a-option value="trading_company">贸易公司</a-option><a-option value="direct_shipper">直接货主</a-option><a-option value="freight_forwarder_partner">货代伙伴</a-option><a-option value="unknown">暂不确定</a-option></a-select></div></div><a-button type="primary" size="large" long :loading="identityLoading" :disabled="Boolean(activeTask)" @click="identify"><template #icon><IconRobot /></template>保存询价并启动 Agent</a-button><div v-if="identityLoading" class="inline-progress"><div class="agent-signal"><span/><span/><span/></div><strong>正在建立客户档案</strong><p>系统正在按邮箱与域名检查已有客户，请勿重复提交。</p></div></div>

        <div v-if="phase === 'agent'" class="agent-result-card"><div class="agent-result-card__head"><span class="agent-avatar">✦</span><div><h2>{{ latestTask?.status === 'failed' ? 'Agent 处理失败' : activeTask ? 'Agent 正在处理您的需求' : 'Agent 已完成当前处理' }}</h2><p>{{ latestTask?.currentStep || '客户档案和获客机会已经建立。' }}</p></div><span :class="['semantic-tag',latestTask?.status === 'failed' ? 'error' : activeTask ? 'info' : 'success']">{{ latestTask?.status || 'completed' }}</span></div><a-progress :percent="(latestTask?.progress || 100)/100" :status="latestTask?.status === 'failed' ? 'danger' : activeTask ? 'normal' : 'success'" /><div class="agent-result-card__steps"><div v-for="task in relatedTasks" :key="task.id"><IconCheckCircle v-if="task.status==='completed'" /><div class="agent-signal" v-else-if="['queued','running','waiting'].includes(task.status)"><span/><span/><span/></div><span v-else class="error-dot">×</span><p><strong>{{ task.currentStep }}</strong><small>{{ task.status }} · {{ task.progress }}%</small></p></div></div><div v-if="latestTask?.error" class="site-error">{{ latestTask.error }}</div><div class="agent-result-card__actions"><a-button @click="resetFlow">重新开始一组演示</a-button><NuxtLink :to="{ path:'/admin/opportunities', query:{ opportunity:opportunityId } }"><a-button type="primary">在运营后台查看完整进度 <IconArrowRight /></a-button></NuxtLink></div></div>
      </section>

      <section id="services" class="service-strip"><div><strong>12</strong><span>已发布演示产品</span></div><div><strong>5</strong><span>Agent 业务任务模式</span></div><div><strong>9</strong><span>统一机会进度阶段</span></div><div><strong>2</strong><span>主动与被动获客入口</span></div></section>
    </main>
    <footer class="site-footer"><div class="site-brand"><span class="site-logo">百</span><strong>百运物流 · 智能获客 PoC</strong></div><span>仅用于内部演示，价格、客户与互动数据均为模拟内容。</span><NuxtLink to="/admin">运营演示台</NuxtLink></footer>
  </div>
</template>

<style scoped>
